// Jonker-Volgenant LAP with a binary heap Dijkstra.
#include <vector>
#include <limits>
#include <cstdint>
#include <queue>
#include <utility>

extern "C" {

int lapjv(int n, const double* cost, int* col_ind) {
    const double INF = 1e300;
    std::vector<double> v(n, 0.0), d(n);
    std::vector<int> x(n, -1), y(n, -1), pred(n);
    std::vector<char> scanned(n);

    using P = std::pair<double, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

    for (int i = 0; i < n; ++i) {
        const double* rowi = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            d[j] = rowi[j] - v[j];
            pred[j] = i;
            scanned[j] = 0;
        }
        pq = std::priority_queue<P, std::vector<P>, std::greater<P>>();
        for (int j = 0; j < n; ++j) pq.emplace(d[j], j);

        int free_col = -1;
        double mind_final = 0.0;
        while (!pq.empty()) {
            auto [mind, jmin] = pq.top();
            pq.pop();
            if (scanned[jmin] || mind > d[jmin]) continue;
            scanned[jmin] = 1;
            int i_match = y[jmin];
            if (i_match < 0) {
                free_col = jmin;
                mind_final = mind;
                break;
            }
            const double* row = cost + (size_t)i_match * n;
            double base = row[jmin] - v[jmin];
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double nd = mind + row[j] - v[j] - base;
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i_match;
                    pq.emplace(nd, j);
                }
            }
        }
        if (free_col < 0) return 1;
        for (int j = 0; j < n; ++j) {
            if (scanned[j]) v[j] += d[j] - mind_final;
        }
        int j = free_col;
        while (true) {
            int i_pred = pred[j];
            y[j] = i_pred;
            int old = x[i_pred];
            x[i_pred] = j;
            if (i_pred == i) break;
            j = old;
        }
    }
    for (int i = 0; i < n; ++i) col_ind[i] = x[i];
    return 0;
}

} // extern C
