{"command":"cat > build/lapjv.cpp << 'EOF'
/*
 * Dense square Jonker-Volgenant assignment.
 * Column reduction + reduction transfer + augmenting row reduction
 * + Dijkstra shortest augmenting paths with dual updates.
 *
 * cost is row-major n*n. Writes col_for_row[i] = assigned column.
 * Returns 0 on success.
 */
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>

static const double BIG = 1e100;

extern "C" int lapjv(int n, const double* cost, int* col_for_row) {
    const int dim = n;
    std::vector<double> u(dim), v(dim, 0.0), d(dim);
    std::vector<int> rowsol(dim, -1), colsol(dim, -1), pred(dim);
    std::vector<int> free_list;
    free_list.reserve(dim);
    std::vector<char> scanned(dim);

    auto C = [&](int i, int j) -> double { return cost[(size_t)i * dim + j]; };

    // ---------- COLUMN REDUCTION ----------
    // Assign each column to a minimum reduced-cost row, uniquely if possible.
    for (int j = dim - 1; j >= 0; --j) {
        double minv = C(0, j);
        int imin = 0;
        for (int i = 1; i < dim; ++i) {
            double val = C(i, j);
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] < 0) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1; // free column
        }
    }
    for (int i = 0; i < dim; ++i) if (rowsol[i] < 0) free_list.push_back(i);

    // ---------- REDUCTION TRANSFER ----------
    {
        std::vector<int> still;
        still.reserve(free_list.size());
        for (int i : free_list) {
            // find minimum and second minimum reduced cost
            double mn1 = BIG, mn2 = BIG;
            int j1 = -1;
            for (int j = 0; j < dim; ++j) {
                double red = C(i, j) - v[j];
                if (red < mn1) { mn2 = mn1; mn1 = red; j1 = j; }
                else if (red < mn2) { mn2 = red; }
            }
            u[i] = mn1;
            int i_old = colsol[j1];
            if (i_old < 0 || mn2 - mn1 > 0.0 && (u[i] - u[i_old] < 0 || /* transfer if unique min */ mn2 > mn1)) {
                // transfer if column free or this row has a unique minimum and improves
            }
            if (colsol[j1] < 0) {
                colsol[j1] = i;
                rowsol[i] = j1;
            } else if (mn2 > mn1) {
                // unique minimum: transfer assignment
                int i2 = colsol[j1];
                // only transfer if i2 is not uniquely better; classical transfer:
                // if row i has a unique min at j1, take it and free i2
                rowsol[i] = j1;
                colsol[j1] = i;
                rowsol[i2] = -1;
                still.push_back(i2);
                v[j1] -= (mn2 - mn1);
            } else {
                still.push_back(i);
            }
        }
        free_list.swap(still);
    }

    // ---------- AUGMENTING ROW REDUCTION (2 passes) ----------
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<int> still;
        still.reserve(free_list.size());
        for (int i : free_list) {
            double mn1 = BIG, mn2 = BIG;
            int j1 = -1, j2 = -1;
            for (int j = 0; j < dim; ++j) {
                double red = C(i, j) - v[j];
                if (red < mn1) { mn2 = mn1; j2 = j1; mn1 = red; j1 = j; }
                else if (red < mn2) { mn2 = red; j2 = j; }
            }
            u[i] = mn2; // set dual so two minima
            if (mn2 > mn1) v[j1] -= (mn2 - mn1);
            int i2 = colsol[j1];
            if (i2 < 0) {
                colsol[j1] = i;
                rowsol[i] = j1;
            } else if (i2 != i) {
                // take j1, free previous
                rowsol[i] = j1;
                colsol[j1] = i;
                rowsol[i2] = -1;
                still.push_back(i2);
            } else {
                still.push_back(i);
            }
        }
        free_list.swap(still);
        if (free_list.empty()) break;
    }

    // ---------- AUGMENTATION (Dijkstra) ----------
    // binary heap
    struct Node { double d; int j; };
    struct Cmp { bool operator()(const Node& a, const Node& b) const { return a.d > b.d; } };

    for (int free_i : free_list) {
        // if already assigned (shouldn't), skip
        if (rowsol[free_i] >= 0) continue;
        std::fill(scanned.begin(), scanned.end(), 0);
        for (int j = 0; j < dim; ++j) {
            d[j] = C(free_i, j) - v[j];
            pred[j] = free_i;
        }
        std::vector<Node> heap;
        heap.reserve(dim);
        auto heap_push = [&](double dist, int j) {
            heap.push_back({dist, j});
            std::push_heap(heap.begin(), heap.end(), Cmp{});
        };
        auto heap_pop = [&]() {
            std::pop_heap(heap.begin(), heap.end(), Cmp{});
            Node n = heap.back(); heap.pop_back(); return n;
        };
        for (int j = 0; j < dim; ++j) heap_push(d[j], j);

        int free_col = -1;
        double mind_final = 0;
        int last_row = free_i;
        while (!heap.empty()) {
            Node nd = heap_pop();
            int jmin = nd.j;
            if (scanned[jmin] || nd.d > d[jmin]) continue;
            scanned[jmin] = 1;
            double mind = nd.d;
            int i_match = colsol[jmin];
            if (i_match < 0) { free_col = jmin; mind_final = mind; break; }
            const double base = C(i_match, jmin) - v[jmin];
            const double* row = cost + (size_t)i_match * dim;
            for (int j = 0; j < dim; ++j) {
                if (scanned[j]) continue;
                double ndist = mind + row[j] - v[j] - base;
                if (ndist < d[j]) {
                    d[j] = ndist;
                    pred[j] = i_match;
                    heap_push(ndist, j);
                }
            }
        }
        if (free_col < 0) return 1;
        for (int j = 0; j < dim; ++j) if (scanned[j]) v[j] += d[j] - mind_final;
        // augment
        int j = free_col;
        while (true) {
            int i_pred = pred[j];
            colsol[j] = i_pred;
            int old = rowsol[i_pred];
            rowsol[i_pred] = j;
            if (i_pred == free_i) break;
            j = old;
        }
    }

    for (int i = 0; i < dim; ++i) col_for_row[i] = rowsol[i];
    return 0;
}
