// Epsilon-scaling auction for the assignment problem, restricted to the
// k nearest columns of each row (plus a fallback full scan if needed).
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <queue>

extern "C" int auction_k(int n, const double* cost, const int* knn, int k,
                         int* col_for_row, double eps_final, int max_cycles) {
    // knn: n * k row-major nearest column indices (must include a feasible matching)
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1);
    double cmax = 0.0;
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < k; ++t)
            cmax = std::max(cmax, cost[(size_t)i * n + knn[(size_t)i * k + t]]);
    double eps = cmax / 4.0;
    if (eps < eps_final) eps = eps_final;

    int cycles = 0;
    while (cycles < max_cycles) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        std::vector<int> unassigned(n);
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        int guard = 0;
        const int guard_max = n * n;
        while (!unassigned.empty() && guard < guard_max) {
            ++guard;
            int i = unassigned.back();
            unassigned.pop_back();
            const int* nbr = knn + (size_t)i * k;
            const double* row = cost + (size_t)i * n;
            int best_j = nbr[0];
            double best = -row[best_j] - price[best_j];
            double second = -1e300;
            for (int t = 1; t < k; ++t) {
                int j = nbr[t];
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            if (second < -1e299) second = best - eps; // only one neighbor
            double bid_price = price[best_j] + (best - second) + eps;
            // price update: new price = -row[best_j] - second + eps = price + (best-second) + eps
            price[best_j] = bid_price;
            int prev = owner[best_j];
            if (prev >= 0) {
                assignment[prev] = -1;
                unassigned.push_back(prev);
            }
            owner[best_j] = i;
            assignment[i] = best_j;
        }
        ++cycles;
        if (eps <= eps_final * 1.0001) break;
        eps = std::max(eps_final, eps * 0.25);
    }
    for (int i = 0; i < n; ++i) col_for_row[i] = assignment[i];
    // check completeness
    for (int i = 0; i < n; ++i) if (assignment[i] < 0) return 1;
    return 0;
}
