                else if (val > second) second = val;
            }
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            if (prev >= 0) {
                assignment[prev] = -1;
                unassigned.push_back(prev);
            }
            owner[best_j] = i;
            assignment[i] = best_j;
        }
        ++scale_rounds;
