#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <numeric>

// Auction on a sparse bipartite graph given as CSR (row -> candidate columns).
// Returns 0 if a perfect matching is found.
extern "C" int auction_csr(int n, const double* cost,
                           const int* csr_ptr, const int* csr_col,
                           int* col_for_row, double eps_final, int* prices_unused) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1);

    double cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        for (int p = csr_ptr[i]; p < csr_ptr[i+1]; ++p) {
            cmax = std::max(cmax, cost[(size_t)i * n + csr_col[p]]);
        }
    }
    double eps = std::max(cmax / 2.0, eps_final);

    for (int round = 0; round < 40; ++round) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        std::vector<int> unassigned(n);
        for (int i = 0; i < n; ++i) unassigned[i] = n - 1 - i;
        long guard = 0;
        const long guard_max = (long)n * 200;
        bool failed = false;
        while (!unassigned.empty()) {
            if (++guard > guard_max) { failed = true; break; }
            int i = unassigned.back();
            unassigned.pop_back();
            int begin = csr_ptr[i], end = csr_ptr[i+1];
            if (begin == end) { failed = true; break; }
            const double* row = cost + (size_t)i * n;
            int best_j = csr_col[begin];
            double best = -row[best_j] - price[best_j];
            double second = -1e300;
            for (int p = begin + 1; p < end; ++p) {
                int j = csr_col[p];
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            if (second < -1e299) second = best - eps;
            price[best_j] += (best - second) + eps;
            int prev = owner[best_j];
            if (prev >= 0) {
                assignment[prev] = -1;
                unassigned.push_back(prev);
            }
            owner[best_j] = i;
            assignment[i] = best_j;
        }
        if (!failed && unassigned.empty()) {
            // success at this eps; continue scaling with prices kept (warm)
            // re-run from current prices? Bertsekas keeps prices across eps.
            // We already reset assignment. Prices persist, which is correct for scaling
            // ONLY if we don't reset prices. We don't. Good.
            // But we reset assignment each round and re-auction with smaller eps using
            // prices from previous round. That's the standard epsilon-scaling auction.
        } else {
            // failed to find matching at this eps
            for (int i = 0; i < n; ++i) col_for_row[i] = -1;
            return 1;
        }
        if (eps <= eps_final * 1.0000001) break;
        eps = std::max(eps_final, eps * 0.2);
    }
    for (int i = 0; i < n; ++i) col_for_row[i] = assignment[i];
    return 0;
}
