#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>

// Find rows whose assigned column is not the unrestricted best under
// value = -cost[i,j] - price[j]. Writes violating row indices.
// Returns number of violations.
extern "C" int find_violations(int n, const double* cost, const int* assignment,
                               const double* price, int* bad_rows, int* best_col,
                               double tol) {
    int nb = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int a = assignment[i];
        double best = -1e300;
        int bj = 0;
        double aval = -row[a] - price[a];
        for (int j = 0; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > best) { best = val; bj = j; }
        }
        best_col[i] = bj;
        if (best > aval + tol) bad_rows[nb++] = i;
    }
    return nb;
}

// Parallel-friendly blocked version using 4-way manual unroll
extern "C" int find_violations_fast(int n, const double* cost, const int* assignment,
                                    const double* price, int* bad_rows, double tol) {
    int nb = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int a = assignment[i];
        double aval = -row[a] - price[a] + tol;
        int j = 0;
        for (; j + 3 < n; j += 4) {
            double v0 = -row[j] - price[j];
