#include <vector>
#include <cstdint>
#include <algorithm>
#include <cmath>
#include <cstring>
#include <numeric>
#include <unordered_set>

struct Cand {
    std::vector<int> cols;
    std::vector<char> present; // size n, 1 if column is a candidate
};

static int auction_once(int n, const double* cost, std::vector<Cand>& cand,
                        std::vector<double>& price, std::vector<int>& assignment,
                        double eps) {
    std::vector<int> owner(n, -1);
    std::fill(assignment.begin(), assignment.end(), -1);
    std::vector<int> unassigned(n);
    for (int i = 0; i < n; ++i) unassigned[i] = n - 1 - i;
    long guard = 0;
    const long guard_max = (long)n * 500;
    while (!unassigned.empty()) {
        if (++guard > guard_max) return 1;
        int i = unassigned.back();
        unassigned.pop_back();
        auto& cols = cand[i].cols;
        if (cols.empty()) return 2;
        const double* row = cost + (size_t)i * n;
        int best_j = cols[0];
        double best = -row[best_j] - price[best_j];
        double second = -1e300;
        for (size_t t = 1; t < cols.size(); ++t) {
            int j = cols[t];
            double val = -row[j] - price[j];
            if (val > best) { second = best; best = val; best_j = j; }
            else if (val > second) second = val;
        }
        if (!(second > -1e299)) second = best - eps;
        price[best_j] += (best - second) + eps;
        int prev = owner[best_j];
        if (prev >= 0) {
            assignment[prev] = -1;
            unassigned.push_back(prev);
        }
        owner[best_j] = i;
        assignment[i] = best_j;
    }
    return 0;
}

// Add the globally best column (under -cost - price) for every locally suboptimal row.
// Returns number of rows that were suboptimal.
static int expand(int n, const double* cost, std::vector<Cand>& cand,
                  const std::vector<double>& price, const std::vector<int>& assignment,
                  double tol) {
    int nb = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int a = assignment[i];
        double aval = -row[a] - price[a] + tol;
        int bj = -1;
        double best = -1e300;
        for (int j = 0; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > best) { best = val; bj = j; }
        }
        if (best > aval) {
            ++nb;
            if (!cand[i].present[bj]) {
                cand[i].present[bj] = 1;
                cand[i].cols.push_back(bj);
            }
            // also add a few runners-up? skip for now
        }
    }
    return nb;
}

extern "C" int solve_auction(int n, const double* cost, const int* knn, int k,
                             int* col_for_row, double eps_final) {
    std::vector<Cand> cand(n);
    for (int i = 0; i < n; ++i) {
        cand[i].present.assign(n, 0);
        cand[i].cols.reserve(k + 16);
        for (int t = 0; t < k; ++t) {
            int j = knn[(size_t)i * k + t];
            if (!cand[i].present[j]) {
                cand[i].present[j] = 1;
                cand[i].cols.push_back(j);
            }
        }
    }
    std::vector<double> price(n, 0.0);
    std::vector<int> assignment(n, -1);

    double cmax = 0.0;
    for (int i = 0; i < n; ++i)
        for (int j : cand[i].cols)
            cmax = std::max(cmax, cost[(size_t)i * n + j]);
    double eps = std::max(cmax / 2.0, eps_final);

    // epsilon scaling on the initial sparse graph
    for (int round = 0; round < 40; ++round) {
        int rc = auction_once(n, cost, cand, price, assignment, eps);
        if (rc != 0) return rc;
        if (eps <= eps_final * 1.0000001) break;
        eps = std::max(eps_final, eps * 0.2);
    }

    // grow candidates until assignment is globally optimal (eps-optimal)
    for (int grow = 0; grow < 30; ++grow) {
        int nb = expand(n, cost, cand, price, assignment, eps_final * 10 + 1e-9);
        if (nb == 0) {
            for (int i = 0; i < n; ++i) col_for_row[i] = assignment[i];
            return 0;
        }
        // re-auction at final eps with expanded candidates, prices kept
        int rc = auction_once(n, cost, cand, price, assignment, eps_final);
        if (rc != 0) {
            // try a slightly larger eps then come back
            rc = auction_once(n, cost, cand, price, assignment, eps_final * 5);
            if (rc != 0) return 10 + rc;
            auction_once(n, cost, cand, price, assignment, eps_final);
        }
    }
    return 3;
}
