// Sparse Jonker-Volgenant / successive shortest paths for assignment
// on a bipartite graph given as CSR (each row has a candidate list).
// cost is the FULL dense matrix (row-major); candidates index into it.
// Returns 0 and a perfect matching if one exists in the candidate graph.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <queue>
#include <utility>

extern "C" int sparse_assign(int n, const double* cost,
                             const int* csr_ptr, const int* csr_col,
                             int* col_for_row) {
    const double INF = 1e100;
    std::vector<double> v(n, 0.0), pot_row(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);

    using P = std::pair<double, int>;

    // initialize v[j] = min cost of edges into j (for a mild start)
    for (int j = 0; j < n; ++j) v[j] = 0.0;

    for (int i = 0; i < n; ++i) {
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        // seed from free row i
        for (int p = csr_ptr[i]; p < csr_ptr[i+1]; ++p) {
            int j = csr_col[p];
            double d = cost[(size_t)i * n + j] - v[j];
            if (d < dist[j]) {
                dist[j] = d;
                pred[j] = i;
                pq.emplace(d, j);
            }
        }
        int free_col = -1;
        double mind_final = 0;
        while (!pq.empty()) {
            auto [dcur, jmin] = pq.top();
            pq.pop();
            if (scanned[jmin] || dcur > dist[jmin]) continue;
            scanned[jmin] = 1;
            int i_match = colsol[jmin];
            if (i_match < 0) { free_col = jmin; mind_final = dcur; break; }
            double base = cost[(size_t)i_match * n + jmin] - v[jmin];
            for (int p = csr_ptr[i_match]; p < csr_ptr[i_match+1]; ++p) {
                int j = csr_col[p];
                if (scanned[j]) continue;
                double nd = dcur + cost[(size_t)i_match * n + j] - v[j] - base;
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = i_match;
                    pq.emplace(nd, j);
                }
            }
        }
        if (free_col < 0) return 1; // no perfect matching in this graph
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind_final;
        int j = free_col;
        while (true) {
            int i_pred = pred[j];
            colsol[j] = i_pred;
            int old = rowsol[i_pred];
            rowsol[i_pred] = j;
            if (i_pred == i) break;
            j = old;
        }
    }
    for (int i = 0; i < n; ++i) col_for_row[i] = rowsol[i];
    return 0;
}
