// Sparse successive-shortest-path assignment with warm start.
// cost: dense row-major n*n
// candidates: CSR
// v: column duals (updated in place)
// rowsol/colsol: matching, -1 = free (updated in place)
// Only free rows are augmented.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <queue>
#include <utility>

extern "C" int sparse_augment(int n, const double* cost,
                              const int* csr_ptr, const int* csr_col,
                              double* v, int* rowsol, int* colsol) {
    const double INF = 1e100;
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    using P = std::pair<double, int>;

    for (int i = 0; i < n; ++i) {
        if (rowsol[i] >= 0) continue;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        for (int p = csr_ptr[i]; p < csr_ptr[i+1]; ++p) {
            int j = csr_col[p];
            double d = cost[(size_t)i * n + j] - v[j];
            if (d < dist[j]) {
                dist[j] = d;
                pred[j] = i;
                pq.emplace(d, j);
            }
        }
        int free_col = -1;
        double mind_final = 0;
        while (!pq.empty()) {
            auto [dcur, jmin] = pq.top();
            pq.pop();
            if (scanned[jmin] || dcur > dist[jmin]) continue;
            scanned[jmin] = 1;
            int i_match = colsol[jmin];
            if (i_match < 0) { free_col = jmin; mind_final = dcur; break; }
            double base = cost[(size_t)i_match * n + jmin] - v[jmin];
            for (int p = csr_ptr[i_match]; p < csr_ptr[i_match+1]; ++p) {
                int j = csr_col[p];
                if (scanned[j]) continue;
                double nd = dcur + cost[(size_t)i_match * n + j] - v[j] - base;
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = i_match;
                    pq.emplace(nd, j);
                }
            }
        }
        if (free_col < 0) return 1;
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind_final;
        int j = free_col;
        while (true) {
            int i_pred = pred[j];
            colsol[j] = i_pred;
            int old = rowsol[i_pred];
            rowsol[i_pred] = j;
            if (i_pred == i) break;
            j = old;
        }
    }
    return 0;
}

// Find rows violating complementary slackness against the FULL cost matrix.
// Adds the best violating column to the candidate list (caller manages presence).
// present: n*n char row-major, 1 if (i,j) already a candidate.
// Returns number of violations. Appends new columns into extra_cols and updates
// counts in add_count[i].
extern "C" int find_and_collect(int n, const double* cost, const double* v,
                                const int* rowsol, char* present,
                                int* add_count, int* add_cols, double tol) {
    int total_new = 0;
    for (int i = 0; i < n; ++i) add_count[i] = 0;
    // add_cols is a flat buffer; we write contiguously and record counts
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        int a = rowsol[i];
        double best_red = row[a] - v[a];
        int bj = -1;
        double bj_red = best_red;
        for (int j = 0; j < n; ++j) {
            double red = row[j] - v[j];
            if (red < bj_red - tol) { bj_red = red; bj = j; }
        }
        if (bj >= 0 && !present[(size_t)i * n + bj]) {
            present[(size_t)i * n + bj] = 1;
            add_cols[total_new++] = bj;
            add_count[i] = 1;
        } else if (bj >= 0) {
            // already present but still violating? shouldn't happen if duals are
            // optimal over the candidate graph. Mark so caller re-solves anyway.
            add_count[i] = -1;
        }
    }
    return total_new;
}
