#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <queue>
#include <utility>

static int augment_free(int n, const double* cost,
                        const std::vector<std::vector<int>>& nbr,
                        std::vector<double>& v,
                        std::vector<int>& rowsol,
                        std::vector<int>& colsol) {
    const double INF = 1e100;
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    using P = std::pair<double, int>;

    for (int i = 0; i < n; ++i) {
        if (rowsol[i] >= 0) continue;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        for (int j : nbr[i]) {
            double d = cost[(size_t)i * n + j] - v[j];
            if (d < dist[j]) {
                dist[j] = d;
                pred[j] = i;
                pq.emplace(d, j);
            }
        }
        if (pq.empty()) return 1;
        int free_col = -1;
        double mind_final = 0;
        while (!pq.empty()) {
            auto [dcur, jmin] = pq.top();
            pq.pop();
            if (scanned[jmin] || dcur > dist[jmin]) continue;
            scanned[jmin] = 1;
            int i_match = colsol[jmin];
            if (i_match < 0) { free_col = jmin; mind_final = dcur; break; }
            double base = cost[(size_t)i_match * n + jmin] - v[jmin];
            const double* row = cost + (size_t)i_match * n;
            for (int j : nbr[i_match]) {
                if (scanned[j]) continue;
                double nd = dcur + row[j] - v[j] - base;
                if (nd < dist[j]) {
                    dist[j] = nd;
                    pred[j] = i_match;
                    pq.emplace(nd, j);
                }
            }
        }
        if (free_col < 0) return 1;
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind_final;
        int j = free_col;
        while (true) {
            int i_pred = pred[j];
            colsol[j] = i_pred;
            int old = rowsol[i_pred];
            rowsol[i_pred] = j;
            if (i_pred == i) break;
            j = old;
        }
    }
    return 0;
}

extern "C" int solve_grow(int n, const double* cost, const int* knn, int k,
                          int* col_for_row, double tol) {
    std::vector<std::vector<int>> nbr(n);
    for (int i = 0; i < n; ++i) {
        nbr[i].assign(knn + (size_t)i * k, knn + (size_t)i * k + k);
        std::sort(nbr[i].begin(), nbr[i].end());
        nbr[i].erase(std::unique(nbr[i].begin(), nbr[i].end()), nbr[i].end());
    }
    std::vector<double> v(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    if (augment_free(n, cost, nbr, v, rowsol, colsol) != 0) return 1;

    std::vector<int> touched;
    touched.reserve(n);
    for (int grow = 0; grow < 50; ++grow) {
        touched.clear();
        for (int i = 0; i < n; ++i) {
            const double* row = cost + (size_t)i * n;
            int a = rowsol[i];
            double thresh = row[a] - v[a] - tol;
            int bj = -1;
            double bj_red = thresh;
            for (int j = 0; j < n; ++j) {
                double red = row[j] - v[j];
                if (red < bj_red) { bj_red = red; bj = j; }
            }
            if (bj >= 0) {
                auto& nb = nbr[i];
                auto it = std::lower_bound(nb.begin(), nb.end(), bj);
                if (it == nb.end() || *it != bj) nb.insert(it, bj);
                int jold = rowsol[i];
                colsol[jold] = -1;
                rowsol[i] = -1;
                touched.push_back(i);
            }
        }
        if (touched.empty()) {
            for (int i = 0; i < n; ++i) col_for_row[i] = rowsol[i];
            return 0;
        }
        if (augment_free(n, cost, nbr, v, rowsol, colsol) != 0) return 2;
    }
    return 3;
}
