{"command":"cat > build/auction.cpp << 'EOF'
// Epsilon-scaling auction for the dense assignment problem, restricted to a
// growing candidate set. Candidates start as the k cheapest columns per row
// and grow by any column that violates complementary slackness, so the result
// is optimal for the full cost matrix.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <numeric>
#include <cstring>
#include <cmath>
#include <thread>

struct RowCand {
    std::vector<int> cols;
    std::vector<char> present;
};

static void auction_phase(int n, const double* cost, std::vector<RowCand>& cand,
                          std::vector<double>& price, std::vector<int>& owner,
                          std::vector<int>& assignment, std::vector<int>& unassigned,
                          double eps) {
    const long guard_max = (long)n * n; // generous; positive eps guarantees termination
    long guard = 0;
    while (!unassigned.empty()) {
        if (++guard > guard_max) return; // caller detects incomplete assignment
        int i = unassigned.back();
        unassigned.pop_back();
        if (assignment[i] >= 0) continue;
        auto& cols = cand[i].cols;
        const double* row = cost + (size_t)i * n;
        int best_j = cols[0];
        double best = -row[best_j] - price[best_j];
        double second = -1e300;
        for (size_t t = 1; t < cols.size(); ++t) {
            int j = cols[t];
            double val = -row[j] - price[j];
            if (val > best) {
                second = best;
                best = val;
                best_j = j;
            } else if (val > second) {
                second = val;
            }
        }
        if (!(second > -1e290)) second = best - eps;
        price[best_j] += (best - second) + eps;
        int prev = owner[best_j];
        if (prev >= 0 && prev != i) {
            assignment[prev] = -1;
            unassigned.push_back(prev);
        }
        owner[best_j] = i;
        assignment[i] = best_j;
    }
}

// Unassign rows that are not eps-happy over their candidate set. Returns count.
static int unassign_unhappy(int n, const double* cost, const std::vector<RowCand>& cand,
                            const std::vector<double>& price, std::vector<int>& owner,
                            std::vector<int>& assignment, std::vector<int>& unassigned,
                            double eps) {
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
        int a = assignment[i];
        if (a < 0) { unassigned.push_back(i); ++cnt; continue; }
        const double* row = cost + (size_t)i * n;
        double aval = -row[a] - price[a];
        bool unhappy = false;
        for (int j : cand[i].cols) {
            if (-row[j] - price[j] > aval + eps) { unhappy = true; break; }
        }
        if (unhappy) {
            owner[a] = -1;
            assignment[i] = -1;
            unassigned.push_back(i);
            ++cnt;
        }
    }
    return cnt;
}

// Global scan: add the best violating column for each row. Returns #violations.
static int grow_candidates(int n, const double* cost, std::vector<RowCand>& cand,
                           const std::vector<double>& price, std::vector<int>& owner,
                           std::vector<int>& assignment, std::vector<int>& unassigned,
                           double tol) {
    const int nthreads = 4;
    std::vector<std::vector<std::pair<int,int>>> found(nthreads);
    auto worker = [&](int tid) {
        int begin = (n * tid) / nthreads;
        int end = (n * (tid + 1)) / nthreads;
        auto& out = found[tid];
        out.reserve(16);
        for (int i = begin; i < end; ++i) {
            int a = assignment[i];
            if (a < 0) continue;
            const double* row = cost + (size_t)i * n;
            double aval = -row[a] - price[a];
            double best = aval;
            int bj = -1;
            const char* pres = cand[i].present.data();
            const double* pr = price.data();
            for (int j = 0; j < n; ++j) {
                if (pres[j]) continue;
                double val = -row[j] - pr[j];
                if (val > best + tol) { best = val; bj = j; }
            }
            if (bj >= 0) out.emplace_back(i, bj);
        }
    };
    std::vector<std::thread> threads;
    for (int t = 0; t < nthreads; ++t) threads.emplace_back(worker, t);
    for (auto& th : threads) th.join();

    int nb = 0;
    for (auto& out : found) {
        for (auto [i, bj] : out) {
            if (!cand[i].present[bj]) {
                cand[i].present[bj] = 1;
                cand[i].cols.push_back(bj);
            }
            int a = assignment[i];
            if (a >= 0) {
                owner[a] = -1;
                assignment[i] = -1;
                unassigned.push_back(i);
            }
            ++nb;
        }
    }
    return nb;
}

extern "C" int solve_auction(int n, const double* cost, int k, int* col_for_row,
                             double eps_final) {
    std::vector<RowCand> cand(n);
    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);
    double cmax = 0.0;
    for (int i = 0; i < n; ++i) {
        cand[i].present.assign(n, 0);
        cand[i].cols.reserve(k + 8);
        const double* row = cost + (size_t)i * n;
        std::iota(order.begin(), order.end(), 0);
        int kk = std::min(k, n);
        std::nth_element(order.begin(), order.begin() + kk, order.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        for (int t = 0; t < kk; ++t) {
            int j = order[t];
            cand[i].present[j] = 1;
            cand[i].cols.push_back(j);
            cmax = std::max(cmax, row[j]);
        }
    }

    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1), unassigned(n);
    for (int i = 0; i < n; ++i) unassigned[i] = n - 1 - i;

    double eps = std::max(cmax / 4.0, eps_final);
    for (int phase = 0; phase < 60; ++phase) {
        auction_phase(n, cost, cand, price, owner, assignment, unassigned, eps);
        for (int i = 0; i < n; ++i) if (assignment[i] < 0) return 1;
        if (eps <= eps_final * 1.0000001) break;
        eps = std::max(eps_final, eps * 0.25);
        unassigned.clear();
        unassign_unhappy(n, cost, cand, price, owner, assignment, unassigned, eps);
    }

    for (int grow = 0; grow < 40; ++grow) {
        unassigned.clear();
        int nb = grow_candidates(n, cost, cand, price, owner, assignment, unassigned, 1e-9);
        if (nb == 0) {
            for (int i = 0; i < n; ++i) col_for_row[i] = assignment[i];
            return 0;
        }
        // continue auction at final epsilon with the new edges
        auction_phase(n, cost, cand, price, owner, assignment, unassigned, eps_final);
        for (int i = 0; i < n; ++i) if (assignment[i] < 0) return 2;
    }
    return 3;
}
