// Successive shortest paths for dense assignment, specialized for uniform
// supplies/demands (a permutation). Column potentials make reduced costs
// nonnegative on the equality subgraph. The global violation scan is
// parallel; augmentation is sequential but only touches violated rows.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <queue>
#include <utility>
#include <thread>
#include <numeric>

static int augment_from(int n, const double* cost,
                        const std::vector<std::vector<int>>& nbr,
                        std::vector<double>& v,
                        std::vector<int>& rowsol,
                        std::vector<int>& colsol,
                        const std::vector<int>& free_rows) {
    const double INF = 1e100;
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<char> scanned(n);
    using P = std::pair<double, int>;

    for (int i : free_rows) {
        if (rowsol[i] >= 0) continue;
        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        for (int j : nbr[i]) {
            double d = cost[(size_t)i * n + j] - v[j];
            if (d < dist[j]) { dist[j] = d; pred[j] = i; pq.emplace(d, j); }
        }
        if (pq.empty()) return 1;
        int free_col = -1;
        double mind_final = 0;
        while (!pq.empty()) {
            auto [dcur, jmin] = pq.top(); pq.pop();
            if (scanned[jmin] || dcur > dist[jmin]) continue;
            scanned[jmin] = 1;
            int i_match = colsol[jmin];
            if (i_match < 0) { free_col = jmin; mind_final = dcur; break; }
            double base = cost[(size_t)i_match * n + jmin] - v[jmin];
            const double* row = cost + (size_t)i_match * n;
            for (int j : nbr[i_match]) {
                if (scanned[j]) continue;
                double nd = dcur + row[j] - v[j] - base;
                if (nd < dist[j]) { dist[j] = nd; pred[j] = i_match; pq.emplace(nd, j); }
            }
        }
        if (free_col < 0) return 1;
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += dist[j] - mind_final;
        int j = free_col;
        while (true) {
            int i_pred = pred[j];
            colsol[j] = i_pred;
            int old = rowsol[i_pred];
            rowsol[i_pred] = j;
            if (i_pred == i) break;
            j = old;
        }
    }
    return 0;
}

extern "C" int solve_ssp(int n, const double* cost, int k, int* col_for_row, double tol) {
    const int nthreads = 4;
    std::vector<std::vector<int>> nbr(n);
    std::vector<int> order(n);
    std::iota(order.begin(), order.end(), 0);

    // parallel k-nearest init
    std::vector<std::thread> threads;
    auto init_worker = [&](int tid) {
        int begin = (n * tid) / nthreads, end = (n * (tid + 1)) / nthreads;
        std::vector<int> ord(n);
        std::iota(ord.begin(), ord.end(), 0);
        for (int i = begin; i < end; ++i) {
            const double* row = cost + (size_t)i * n;
            std::iota(ord.begin(), ord.end(), 0);
            int kk = std::min(k, n);
            std::nth_element(ord.begin(), ord.begin() + kk, ord.end(),
                             [&](int a, int b) { return row[a] < row[b]; });
            auto& nb = nbr[i];
            nb.assign(ord.begin(), ord.begin() + kk);
            std::sort(nb.begin(), nb.end());
            nb.erase(std::unique(nb.begin(), nb.end()), nb.end());
        }
    };
    for (int t = 0; t < nthreads; ++t) threads.emplace_back(init_worker, t);
    for (auto& th : threads) th.join();

    std::vector<double> v(n, 0.0);
    std::vector<int> rowsol(n, -1), colsol(n, -1);
    std::vector<int> all(n);
    std::iota(all.begin(), all.end(), 0);
    if (augment_from(n, cost, nbr, v, rowsol, colsol, all) != 0) return 1;

    std::vector<int> touched;
    touched.reserve(n);
    std::vector<std::vector<std::pair<int,int>>> found(nthreads);

    for (int grow = 0; grow < 60; ++grow) {
        for (auto& f : found) f.clear();
        threads.clear();
        auto scan = [&](int tid) {
            int begin = (n * tid) / nthreads, end = (n * (tid + 1)) / nthreads;
            auto& out = found[tid];
            for (int i = begin; i < end; ++i) {
                const double* row = cost + (size_t)i * n;
                int a = rowsol[i];
                double thresh = row[a] - v[a] - tol;
                const auto& nb = nbr[i];
                int bj = -1;
                double best = thresh;
                // scan all columns, skip those already in nbr via binary search only on hit
                for (int j = 0; j < n; ++j) {
                    double red = row[j] - v[j];
                    if (red < best) {
                        // confirm not already a neighbor
                        auto it = std::lower_bound(nb.begin(), nb.end(), j);
                        if (it != nb.end() && *it == j) continue;
                        best = red;
                        bj = j;
                    }
                }
                if (bj >= 0) out.emplace_back(i, bj);
            }
        };
        for (int t = 0; t < nthreads; ++t) threads.emplace_back(scan, t);
        for (auto& th : threads) th.join();

        touched.clear();
        bool any = false;
        for (auto& out : found) {
            for (auto [i, bj] : out) {
                any = true;
                auto& nb = nbr[i];
                auto it = std::lower_bound(nb.begin(), nb.end(), bj);
                if (it == nb.end() || *it != bj) nb.insert(it, bj);
                if (rowsol[i] >= 0) {
                    colsol[rowsol[i]] = -1;
                    rowsol[i] = -1;
                    touched.push_back(i);
                }
            }
        }
        if (!any) {
            for (int i = 0; i < n; ++i) col_for_row[i] = rowsol[i];
            return 0;
        }
        if (augment_from(n, cost, nbr, v, rowsol, colsol, touched) != 0) return 2;
    }
    return 3;
}
