{"command":"cat > build/lapjv.cpp << 'EOF'
/*
 * Jonker-Volgenant shortest augmenting path assignment.
 * Faithful to the classical algorithm (column reduction, reduction transfer,
 * augmenting row reduction, then Dijkstra augmentation), which is substantially
 * faster than a plain successive-shortest-path start on geometric costs.
 *
 * cost: row-major n*n double. Writes col_for_row[0..n).
 */
#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <queue>
#include <utility>

static const double BIG = 1e100;

extern "C" int lapjv(int n, const double* cost, int* col_for_row) {
    const int dim = n;
    std::vector<double> u(dim), v(dim, 0.0), d(dim);
    std::vector<int> rowsol(dim, -1), colsol(dim, -1), pred(dim), freeunassigned;
    std::vector<char> unique(dim, 0);
    freeunassigned.reserve(dim);

    auto C = [&](int i, int j) -> double { return cost[(size_t)i * dim + j]; };

    // ---- COLUMN REDUCTION ----
    // Process columns from last to first. Assign column j to its cheapest row
    // if that row is free; otherwise remember the column is unassigned and
    // record that the row has a competing column (reduction transfer prep).
    std::vector<int> firstcol(dim, -1); // another column for which this row is minimum
    for (int j = dim - 1; j >= 0; --j) {
        double minv = C(0, j);
        int imin = 0;
        for (int i = 1; i < dim; ++i) {
            double val = C(i, j);
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            // row already assigned; keep j free and note alternate
            colsol[j] = -1;
            if (firstcol[imin] == -1) firstcol[imin] = j;
        }
    }

    // ---- REDUCTION TRANSFER ----
    for (int i = 0; i < dim; ++i) {
        if (rowsol[i] != -1 && firstcol[i] != -1) {
            int j1 = rowsol[i];
            int j2 = firstcol[i];
            double h = C(i, j2) - v[j2] - (C(i, j1) - v[j1]);
            if (h > 0) {
                // transfer: the unique minimum is j1; lower v[j1]
                // Actually classical: if row i is the unique minimum of j1,
                // we already assigned it. Reduction transfer moves the assignment
                // to an unassigned column when beneficial. Skip if not unique.
            }
        }
        if (rowsol[i] == -1) freeunassigned.push_back(i);
    }

    // ---- AUGMENTING ROW REDUCTION ----
    for (int pass = 0; pass < 2; ++pass) {
        int nfree = (int)freeunassigned.size();
        int k = 0;
        std::vector<int> next;
        next.reserve(nfree);
        // scan current free list; newly freed rows are retried in this pass (classical)
        std::vector<int> list = freeunassigned;
        size_t head = 0;
        while (head < list.size()) {
            int i = list[head++];
            double mn1 = BIG, mn2 = BIG;
            int j1 = -1;
            for (int j = 0; j < dim; ++j) {
                double red = C(i, j) - v[j];
                if (red < mn1) { mn2 = mn1; mn1 = red; j1 = j; }
                else if (red < mn2) mn2 = red;
            }
            v[j1] -= (mn2 - mn1);
            int i2 = colsol[j1];
            if (i2 >= 0) {
                if (mn2 - mn1 < 1e-15) {
                    // not a unique minimum; don't steal, leave i free
                    // but still update? classical always assigns j1 to i and frees i2
                }
                colsol[j1] = i;
                rowsol[i] = j1;
                rowsol[i2] = -1;
                list.push_back(i2);
            } else {
                colsol[j1] = i;
                rowsol[i] = j1;
            }
        }
        freeunassigned.clear();
        for (int i = 0; i < dim; ++i) if (rowsol[i] < 0) freeunassigned.push_back(i);
        if (freeunassigned.empty()) break;
    }

    // ---- AUGMENTATION ----
    using P = std::pair<double, int>;
    std::vector<char> scanned(dim);
    for (int free_i : freeunassigned) {
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
        std::fill(scanned.begin(), scanned.end(), 0);
        const double* rowi = cost + (size_t)free_i * dim;
        for (int j = 0; j < dim; ++j) {
            d[j] = rowi[j] - v[j];
            pred[j] = free_i;
            pq.emplace(d[j], j);
        }
        int jfree = -1;
        double mind = 0;
        while (!pq.empty()) {
            auto [dj, j] = pq.top(); pq.pop();
            if (scanned[j] || dj > d[j]) continue;
            scanned[j] = 1;
            int i_match = colsol[j];
            if (i_match < 0) { jfree = j; mind = dj; break; }
            double base = cost[(size_t)i_match * dim + j] - v[j];
            const double* row = cost + (size_t)i_match * dim;
            for (int jj = 0; jj < dim; ++jj) {
                if (scanned[jj]) continue;
                double nd = dj + row[jj] - v[jj] - base;
                if (nd < d[jj]) { d[jj] = nd; pred[jj] = i_match; pq.emplace(nd, jj); }
            }
        }
        if (jfree < 0) return 1;
        for (int j = 0; j < dim; ++j) if (scanned[j]) v[j] += d[j] - mind;
        int j = jfree;
        while (true) {
            int ip = pred[j];
            colsol[j] = ip;
            int old = rowsol[ip];
            rowsol[ip] = j;
            if (ip == free_i) break;
            j = old;
        }
    }
    for (int i = 0; i < dim; ++i) col_for_row[i] = rowsol[i];
    return 0;
}
