// Jacobi (synchronous) epsilon-scaling auction.
// Each iteration every unassigned row computes a bid from the current prices,
// then all bids are applied at once. Bids only look at the k cheapest columns
// of a row plus any columns added during optimality repair, so each iteration
// is O(k) per row and vectorizes well.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <numeric>
#include <cstring>
#include <cmath>
#include <thread>

struct Cand {
    std::vector<int> cols;
    std::vector<char> present;
};

extern "C" int solve_jacobi(int n, const double* cost, int k, int* col_for_row, double eps_final) {
    const int nthreads = 4;
    std::vector<Cand> cand(n);
    double cmax = 0.0;
    {
        std::vector<std::thread> threads;
        auto init = [&](int tid) {
            int b = (n * tid) / nthreads, e = (n * (tid + 1)) / nthreads;
            std::vector<int> ord(n);
            for (int i = b; i < e; ++i) {
                const double* row = cost + (size_t)i * n;
                std::iota(ord.begin(), ord.end(), 0);
                int kk = std::min(k, n);
                std::nth_element(ord.begin(), ord.begin() + kk, ord.end(),
                                 [&](int a, int c) { return row[a] < row[c]; });
                cand[i].present.assign(n, 0);
                cand[i].cols.reserve(kk + 8);
                for (int t = 0; t < kk; ++t) {
                    int j = ord[t];
                    cand[i].present[j] = 1;
                    cand[i].cols.push_back(j);
                }
            }
        };
        for (int t = 0; t < nthreads; ++t) threads.emplace_back(init, t);
        for (auto& th : threads) th.join();
    }
    for (int i = 0; i < n; ++i)
        for (int j : cand[i].cols) cmax = std::max(cmax, cost[(size_t)i * n + j]);

    std::vector<double> price(n, 0.0), bid_price(n, 0.0);
    std::vector<int> high_bidder(n, -1), assignment(n, -1), owner(n, -1);
    std::vector<char> unassigned(n, 1);

    auto run_phase = [&](double eps, int max_iter) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        std::fill(unassigned.begin(), unassigned.end(), 1);
        int nfree = n;
        for (int it = 0; it < max_iter && nfree > 0; ++it) {
            std::fill(high_bidder.begin(), high_bidder.end(), -1);
            std::fill(bid_price.begin(), bid_price.end(), -1e300);
            // parallel bids
            std::vector<std::thread> threads;
            auto bid = [&](int tid) {
                int b = (n * tid) / nthreads, e = (n * (tid + 1)) / nthreads;
                // thread-local bid buffers to avoid races, merged after
            };
