            for (int i = 0; i < n; ++i) {
                if (!unassigned[i]) continue;
                const double* row = cost + (size_t)i * n;
                auto& cols = cand[i].cols;
                int best_j = cols[0];
                double best = -row[best_j] - price[best_j];
                double second = -1e300;
                for (size_t t = 1; t < cols.size(); ++t) {
                    int j = cols[t];
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; best_j = j; }
                    else if (val > second) second = val;
                }
                if (!(second > -1e290)) second = best - eps;
                double bp = price[best_j] + (best - second) + eps;
                if (bp > bid_price[best_j]) { bid_price[best_j] = bp; high_bidder[best_j] = i; }
            }
            // apply
            std::fill(unassigned.begin(), unassigned.end(), 0);
            nfree = 0;
            for (int j = 0; j < n; ++j) {
                int i = high_bidder[j];
                if (i < 0) continue;
                price[j] = bid_price[j];
                int prev = owner[j];
                if (prev >= 0 && prev != i) assignment[prev] = -1;
                owner[j] = i;
                assignment[i] = j;
            }
            for (int i = 0; i < n; ++i) if (assignment[i] < 0) { unassigned[i] = 1; ++nfree; }
        }
        return nfree == 0;
    };

    double eps = std::max(cmax / 4.0, eps_final);
    for (int phase = 0; phase < 40; ++phase) {
        if (!run_phase(eps, n * 4)) return 1;
        if (eps <= eps_final * 1.0000001) break;
        eps = std::max(eps_final, eps * 0.25);
    }

    // grow until globally eps-optimal
    for (int grow = 0; grow < 40; ++grow) {
        std::vector<std::vector<std::pair<int,int>>> found(nthreads);
        std::vector<std::thread> threads;
        auto scan = [&](int tid) {
            int b = (n * tid) / nthreads, e = (n * (tid + 1)) / nthreads;
            for (int i = b; i < e; ++i) {
                int a = assignment[i];
                const double* row = cost + (size_t)i * n;
                double aval = -row[a] - price[a];
                const char* pres = cand[i].present.data();
                double best = aval;
                int bj = -1;
                for (int j = 0; j < n; ++j) {
                    if (pres[j]) continue;
                    double val = -row[j] - price[j];
                    if (val > best + 1e-9) { best = val; bj = j; }
                }
                if (bj >= 0) found[tid].emplace_back(i, bj);
            }
        };
        for (int t = 0; t < nthreads; ++t) threads.emplace_back(scan, t);
        for (auto& th : threads) th.join();
        int nb = 0;
        for (auto& f : found) {
            for (auto [i, bj] : f) {
                if (!cand[i].present[bj]) {
                    cand[i].present[bj] = 1;
                    cand[i].cols.push_back(bj);
                    ++nb;
                }
            }
        }
        if (nb == 0) {
            for (int i = 0; i < n; ++i) col_for_row[i] = assignment[i];
            return 0;
        }
        if (!run_phase(eps_final, n * 4)) return 2;
    }
    return 3;
}
