/*
 * Classical Jonker-Volgenant dense LAP (square), row-major costs.
 * Column reduction + reduction transfer + augmenting row reduction
 * + shortest augmenting paths.
 */
#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <cstdio>

static const double BIG = 1e100;

extern "C" int lapjv(int n, const double* cost, int* col_for_row) {
    const int dim = n;
    std::vector<double> u(dim, 0.0), v(dim, 0.0), d(dim);
    std::vector<int> rowsol(dim, -1), colsol(dim, -1), pred(dim);
    std::vector<int> free_rows, collist(dim), matches(dim, 0);
    std::vector<char> scanned(dim);

    // ===================== COLUMN REDUCTION =====================
    for (int j = dim - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < dim; ++i) {
            double val = cost[(size_t)i * dim + j];
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }
    for (int i = 0; i < dim; ++i) if (rowsol[i] < 0) free_rows.push_back(i);

    // ===================== REDUCTION TRANSFER =====================
    {
        std::vector<int> still;
        still.reserve(free_rows.size());
        for (int i : free_rows) {
            double mn1 = BIG, mn2 = BIG;
            int j1 = 0;
            const double* row = cost + (size_t)i * dim;
            for (int j = 0; j < dim; ++j) {
                double red = row[j] - v[j];
                if (red < mn2) {
                    if (red >= mn1) { mn2 = red; }
                    else { mn2 = mn1; mn1 = red; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (mn2 - mn1 > 1e-15) v[j1] -= (mn2 - mn1); // unique minimum
            if (i0 < 0) {
                colsol[j1] = i;
                rowsol[i] = j1;
            } else if (mn2 - mn1 > 1e-15) {
                // transfer assignment from i0 to i; i0 becomes free
                rowsol[i] = j1;
                colsol[j1] = i;
                rowsol[i0] = -1;
                still.push_back(i0);
            } else {
                still.push_back(i);
            }
        }
        free_rows.swap(still);
    }

    // ===================== AUGMENTING ROW REDUCTION =====================
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<int> list = free_rows;
        free_rows.clear();
        size_t head = 0;
        int guard = 0;
        const int guard_max = dim * 4;
        while (head < list.size() && guard < guard_max) {
            ++guard;
            int i = list[head++];
            if (rowsol[i] >= 0) continue;
            double mn1 = BIG, mn2 = BIG;
            int j1 = 0;
            const double* row = cost + (size_t)i * dim;
            for (int j = 0; j < dim; ++j) {
                double red = row[j] - v[j];
                if (red < mn2) {
                    if (red >= mn1) mn2 = red;
                    else { mn2 = mn1; mn1 = red; j1 = j; }
                }
            }
            double h = mn2 - mn1;
            v[j1] -= h;
            int i0 = colsol[j1];
            colsol[j1] = i;
            rowsol[i] = j1;
            if (i0 >= 0 && i0 != i) {
                rowsol[i0] = -1;
                if (h > 1e-15) list.push_back(i0); // unique: previous row goes to end
                else free_rows.push_back(i0);      // not unique: defer
            }
        }
        for (size_t t = head; t < list.size(); ++t) if (rowsol[list[t]] < 0) free_rows.push_back(list[t]);
        if (free_rows.empty()) break;
    }

    int nfree = 0;
    for (int i = 0; i < dim; ++i) if (rowsol[i] < 0) ++nfree;
    // fprintf(stderr, "free after init: %d\n", nfree);

    // ===================== AUGMENTATION =====================
    // Dense (linear-scan) Dijkstra: for the few remaining free rows this is
    // faster than a heap because of sequential memory access.
    for (int i = 0; i < dim; ++i) {
        if (rowsol[i] >= 0) continue;
        std::fill(scanned.begin(), scanned.end(), 0);
        const double* rowi = cost + (size_t)i * dim;
        double mn = BIG;
        int jmin0 = 0;
        for (int j = 0; j < dim; ++j) {
            double dj = rowi[j] - v[j];
            d[j] = dj;
            pred[j] = i;
            if (dj < mn) { mn = dj; jmin0 = j; }
        }
        int last = -1;
        int jcur = jmin0;
        scanned[jcur] = 1;
        while (true) {
            if (colsol[jcur] < 0) { last = jcur; break; }
            int i_match = colsol[jcur];
            double base = cost[(size_t)i_match * dim + jcur] - v[jcur];
            const double* row = cost + (size_t)i_match * dim;
            double h = d[jcur];
            double mn2 = BIG;
            int jnext = -1;
            for (int j = 0; j < dim; ++j) {
                if (scanned[j]) continue;
                double nd = h + row[j] - v[j] - base;
                if (nd < d[j]) { d[j] = nd; pred[j] = i_match; }
                if (d[j] < mn2) { mn2 = d[j]; jnext = j; }
            }
            if (jnext < 0) return 1;
            scanned[jnext] = 1;
            jcur = jnext;
        }
        // dual update
        double mind = d[last];
        for (int j = 0; j < dim; ++j) if (scanned[j]) v[j] += d[j] - mind;
        // augment along pred
        int j = last;
        while (true) {
            int ip = pred[j];
            colsol[j] = ip;
            int old = rowsol[ip];
            rowsol[ip] = j;
            if (ip == i) break;
            j = old;
        }
    }
    for (int i = 0; i < dim; ++i) col_for_row[i] = rowsol[i];
    return 0;
}
