 * Cost-scaling assignment (Goldberg-Kennedy / push-relabel style) for a
 * square dense cost matrix. Uniform supply and demand of 1.
 *
 * Maintains epsilon-optimality: reduced costs of residual edges are >= -eps.
 * Epsilon starts large and is scaled down to machine precision.
 *
 * This is a straightforward implementation meant to be measured, not a
 * finely tuned one.
 */
#include <vector>
#include <cstdint>
#include <algorithm>
#include <cstring>
#include <cmath>
#include <queue>

extern "C" int cost_scale(int n, const double* cost, int* col_for_row) {
    // prices p[j] on columns, potentials u[i] on rows.
    // reduced cost rc(i,j) = cost(i,j) - u[i] - p[j]
    // assignment: each row matched to one column.
    // We use the auction-like cost scaling of Bertsekas with a global
    // epsilon schedule but process rows in a Gauss-Seidel order and keep
    // a candidate list of the k best columns, expanding on demand.
    const int K = 32;
    std::vector<std::vector<int>> nbr(n);
    std::vector<int> ord(n);
    for (int i = 0; i < n; ++i) {
        std::iota(ord.begin(), ord.end(), 0);
        const double* row = cost + (size_t)i * n;
        std::nth_element(ord.begin(), ord.begin() + K, ord.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        nbr[i].assign(ord.begin(), ord.begin() + K);
    }
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assignment(n, -1);

    double cmax = 0;
    for (int i = 0; i < n; ++i)
        for (int j : nbr[i]) cmax = std::max(cmax, cost[(size_t)i * n + j]);
    double eps = cmax / 2.0;
    const double eps_final = 1e-12;

    auto phase = [&](double e) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assignment.begin(), assignment.end(), -1);
        std::vector<int> unassigned(n);
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        long guard = 0;
        const long guard_max = (long)n * n;
        while (!unassigned.empty()) {
            if (++guard > guard_max) return false;
            int i = unassigned.back();
            unassigned.pop_back();
            const double* row = cost + (size_t)i * n;
            int best_j = nbr[i][0];
            double best = -row[best_j] - price[best_j];
            double second = -1e300;
            for (size_t t = 1; t < nbr[i].size(); ++t) {
                int j = nbr[i][t];
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; best_j = j; }
                else if (val > second) second = val;
            }
            if (!(second > -1e290)) second = best - e;
            price[best_j] += (best - second) + e;
            int prev = owner[best_j];
            if (prev >= 0) { assignment[prev] = -1; unassigned.push_back(prev); }
            owner[best_j] = i;
            assignment[i] = best_j;
        }
        return true;
    };

    for (int s = 0; s < 40; ++s) {
        if (!phase(eps)) return 1;
        if (eps <= eps_final) break;
        eps = std::max(eps_final, eps * 0.25);
    }
    for (int i = 0; i < n; ++i) col_for_row[i] = assignment[i];
    return 0;
}
