// Synchronous (Jacobi) epsilon-scaling auction on a growing candidate set.
#include <vector>
#include <cstdint>
#include <algorithm>
#include <numeric>
#include <cstring>
#include <cmath>
#include <thread>
#include <cstdio>

struct Cand {
    std::vector<int> cols;
    std::vector<char> present;
};

extern "C" int solve_jacobi(int n, const double* cost, int k, int* col_for_row, double eps_final) {
    const int nthreads = 4;
    std::vector<Cand> cand(n);
    double cmax = 0.0;
    {
        std::vector<std::thread> threads;
        auto init = [&](int tid) {
            int b = n * tid / nthreads, e = n * (tid + 1) / nthreads;
            std::vector<int> ord(n);
            for (int i = b; i < e; ++i) {
                const double* row = cost + (size_t)i * n;
                std::iota(ord.begin(), ord.end(), 0);
                int kk = std::min(k, n);
                std::nth_element(ord.begin(), ord.begin() + kk, ord.end(),
                                 [&](int a, int c) { return row[a] < row[c]; });
                cand[i].present.assign(n, 0);
                cand[i].cols.reserve(kk + 32);
                for (int t = 0; t < kk; ++t) {
                    int j = ord[t];
                    cand[i].present[j] = 1;
                    cand[i].cols.push_back(j);
                    cmax = std::max(cmax, row[j]); // racy but benign
                }
            }
        };
        for (int t = 0; t < nthreads; ++t) threads.emplace_back(init, t);
        for (auto& th : threads) th.join();
    }
    for (int i = 0; i < n; ++i)
        for (int j : cand[i].cols) cmax = std::max(cmax, cost[(size_t)i * n + j]);

    std::vector<double> price(n, 0.0), bid_amt(n);
    std::vector<int> high(n, -1), owner(n, -1), assignment(n, -1);
    std::vector<char> free(n, 1);
    std::vector<int> freelist(n);

    auto phase = [&](double eps, int max_iter, bool all_free) -> bool {
        if (all_free) {
            std::fill(owner.begin(), owner.end(), -1);
            std::fill(assignment.begin(), assignment.end(), -1);
            std::fill(free.begin(), free.end(), 1);
        }
        int nfree = 0;
        for (int i = 0; i < n; ++i) if (free[i] || assignment[i] < 0) { free[i] = 1; ++nfree; }
        for (int it = 0; it < max_iter && nfree; ++it) {
            std::fill(high.begin(), high.end(), -1);
            int nf = 0;
            for (int i = 0; i < n; ++i) if (free[i]) freelist[nf++] = i;
            for (int t = 0; t < nf; ++t) {
                int i = freelist[t];
                const double* row = cost + (size_t)i * n;
                auto& cols = cand[i].cols;
                int best_j = cols[0];
                double best = -row[best_j] - price[best_j];
                double second = -1e300;
                for (size_t p = 1; p < cols.size(); ++p) {
                    int j = cols[p];
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; best_j = j; }
                    else if (val > second) second = val;
                }
                if (!(second > -1e290)) second = best - eps;
                double bp = price[best_j] + (best - second) + eps;
                if (high[best_j] < 0 || bp > bid_amt[best_j]) {
                    bid_amt[best_j] = bp;
                    high[best_j] = i;
                }
            }
            std::fill(free.begin(), free.end(), 0);
            nfree = 0;
            for (int j = 0; j < n; ++j) {
                int i = high[j];
                if (i < 0) continue;
                price[j] = bid_amt[j];
                int prev = owner[j];
                if (prev >= 0 && prev != i) { assignment[prev] = -1; }
                owner[j] = i;
                assignment[i] = j;
            }
            for (int i = 0; i < n; ++i)
                if (assignment[i] < 0) { free[i] = 1; ++nfree; }
        }
        return nfree == 0;
    };

    double eps = std::max(cmax / 4.0, eps_final);
    int phase_count = 0;
    for (; phase_count < 40; ++phase_count) {
        if (!phase(eps, n * 2, true)) return 1;
        if (eps <= eps_final * 1.0000001) break;
        eps = std::max(eps_final, eps * 0.25);
    }

    for (int grow = 0; grow < 30; ++grow) {
        std::vector<std::vector<std::pair<int,int>>> found(nthreads);
        std::vector<std::thread> threads;
        auto scan = [&](int tid) {
            int b = n * tid / nthreads, e = n * (tid + 1) / nthreads;
            for (int i = b; i < e; ++i) {
                int a = assignment[i];
                if (a < 0) continue;
                const double* row = cost + (size_t)i * n;
                double aval = -row[a] - price[a];
                const char* pres = cand[i].present.data();
                for (int j = 0; j < n; ++j) {
                    if (pres[j]) continue;
                    if (-row[j] - price[j] > aval + 1e-9) found[tid].emplace_back(i, j);
                }
            }
        };
        for (int t = 0; t < nthreads; ++t) threads.emplace_back(scan, t);
        for (auto& th : threads) th.join();
        int added = 0;
        for (auto& f : found)
            for (auto [i, j] : f)
                if (!cand[i].present[j]) { cand[i].present[j] = 1; cand[i].cols.push_back(j); ++added; }
        if (added == 0) {
            for (int i = 0; i < n; ++i) col_for_row[i] = assignment[i];
            return 0;
        }
        // rescale a little so the new edges can be absorbed, then tighten
        double e = std::max(eps_final * 16, 1e-8);
        for (int s = 0; s < 8; ++s) {
            if (!phase(e, n * 2, true)) return 2;
            if (e <= eps_final * 1.0000001) break;
            e = std::max(eps_final, e * 0.25);
        }
    }
    return 3;
}
