// Jonker-Volgenant assignment. The augmenting-path stage processes a small
// batch of matched rows per Dijkstra step so each cost row is loaded once
// and reused across the batch (blocked shortest paths).
#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>

static const double BIG = 1e100;

extern "C" int lapjv(int n, const double* cost, int* col_for_row) {
    const int dim = n;
    std::vector<double> v(dim, 0.0), d(dim);
    std::vector<int> rowsol(dim, -1), colsol(dim, -1), pred(dim);
    std::vector<int> free_rows, matches(dim, 0);
    std::vector<char> scanned(dim);

    for (int j = dim - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < dim; ++i) {
            double val = cost[(size_t)i * dim + j];
            if (val < minv) { minv = val; imin = i; }
