                if (colsol[jn] < 0) { last = jn; break; }
            }
            if (frontier.empty()) return 1;
            bool hit_free = colsol[frontier.back()] < 0 && last == frontier.back();
            // relax all matched rows in the frontier in a blocked pass:
            // for each column j, compute nd from every frontier row and keep min
            for (int j = 0; j < dim; ++j) {
                if (scanned[j]) continue;
                double best = d[j];
                int bp = pred[j];
                for (int jc : frontier) {
                    int im = colsol[jc];
                    if (im < 0) continue;
                    double nd = d[jc] + cost[(size_t)im * dim + j] - v[j] - (cost[(size_t)im * dim + jc] - v[jc]);
