                }
                d[j] = best; pred[j] = bp;
            }
            if (hit_free) break;
        }
        double mind = d[last];
        for (int j = 0; j < dim; ++j) if (scanned[j]) v[j] += d[j] - mind;
        int j = last;
        while (true) {
            int ip = pred[j];
            colsol[j] = ip;
            int old = rowsol[ip];
            rowsol[ip] = j;
            if (ip == i) break;
            j = old;
        }
    }
    for (int i = 0; i < dim; ++i) col_for_row[i] = rowsol[i];
    return 0;
