        std::iota(ord.begin(), ord.end(), 0);
        const double* row = cost + (size_t)i * dim;
        std::nth_element(ord.begin(), ord.begin() + K, ord.end(),
                         [&](int a, int b) { return row[a] < row[b]; });
        std::copy(ord.begin(), ord.begin() + K, band.begin() + (size_t)i * K);
    }
