            const double* row = cost + (size_t)im * dim;
            double h = d[jcur];
            // relax band first
            for (int t = 0; t < K; ++t) {
                int j = band[(size_t)im * K + t];
                if (scanned[j]) continue;
                double nd = h + row[j] - v[j] - base;
                if (nd < d[j]) { d[j] = nd; pred[j] = im; }
            }
            // relax the rest only if some rest-column could beat the best band column
            double band_best = BIG;
            for (int t = 0; t < K; ++t) {
                int j = band[(size_t)im * K + t];
                if (!scanned[j] && d[j] < band_best) band_best = d[j];
            }
            for (int j = 0; j < dim; ++j) {
                if (scanned[j]) continue;
                double nd = h + row[j] - v[j] - base;
                if (nd < d[j]) { d[j] = nd; pred[j] = im; }
            }
        }
        double mind = d[last];
        for (int j = 0; j < dim; ++j) if (scanned[j]) v[j] += d[j] - mind;
        int j = last;
        while (true) {
            int ip = pred[j]; colsol[j] = ip; int old = rowsol[ip]; rowsol[ip] = j;
            if (ip == i) break; j = old;
        }
    }
    for (int i = 0; i < dim; ++i) col_for_row[i] = rowsol[i];
    return 0;
}
