#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <arm_neon.h>

static const double BIG = 1e100;

static inline void relax_row(const double* row, const double* v, double* d, int* pred,
                             const uint8_t* scanned, int dim, int im, double h, double base) {
    // d[j] = min(d[j], h + row[j] - v[j] - base), pred[j] = im on improvement.
    // Skip scanned columns.
    const double add = h - base;
    int j = 0;
    // scalar head to align
    for (; j < dim && ((reinterpret_cast<uintptr_t>(row + j) & 15) || scanned[j]); ++j) {
        if (scanned[j]) continue;
        double nd = add + row[j] - v[j];
        if (nd < d[j]) { d[j] = nd; pred[j] = im; }
    }
    // groups of 2 doubles (128-bit), only when the next 2 are both unscanned
    for (; j + 1 < dim; ) {
        if (scanned[j] || scanned[j+1]) {
            if (!scanned[j]) {
                double nd = add + row[j] - v[j];
                if (nd < d[j]) { d[j] = nd; pred[j] = im; }
            }
            if (!scanned[j+1]) {
                double nd = add + row[j+1] - v[j+1];
                if (nd < d[j+1]) { d[j+1] = nd; pred[j+1] = im; }
            }
            j += 2;
