        float64x2_t rj = vld1q_f64(row + j);
        float64x2_t vj = vld1q_f64(v + j);
        float64x2_t dj = vld1q_f64(d + j);
        float64x2_t nd = vsubq_f64(vaddq_f64(rj, vdupq_n_f64(add)), vj);
        uint64x2_t mask = vcltq_f64(nd, dj);
        float64x2_t merged = vbslq_f64(mask, nd, dj);
        vst1q_f64(d + j, merged);
        if (vgetq_lane_u64(mask, 0)) pred[j] = im;
        if (vgetq_lane_u64(mask, 1)) pred[j+1] = im;
        j += 2;
    }
    for (; j < dim; ++j) {
        if (scanned[j]) continue;
        double nd = add + row[j] - v[j];
        if (nd < d[j]) { d[j] = nd; pred[j] = im; }
    }
