#include <vector>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <immintrin.h>

static const double BIG = 1e100;

// d[j] = min(d[j], add + row[j] - v[j]) for unscanned j; pred[j] = im on update.
static inline void relax_row(const double* row, const double* v, double* d, int* pred,
                             const uint8_t* scanned, int dim, int im, double add) {
    int j = 0;
    const __m256d addv = _mm256_set1_pd(add);
    for (; j + 3 < dim; j += 4) {
        // if any of the 4 is scanned, do scalar for this group
        if (scanned[j] | scanned[j+1] | scanned[j+2] | scanned[j+3]) {
            for (int k = 0; k < 4; ++k) {
                if (scanned[j+k]) continue;
                double nd = add + row[j+k] - v[j+k];
                if (nd < d[j+k]) { d[j+k] = nd; pred[j+k] = im; }
            }
            continue;
        }
        __m256d rj = _mm256_loadu_pd(row + j);
        __m256d vj = _mm256_loadu_pd(v + j);
        __m256d dj = _mm256_loadu_pd(d + j);
        __m256d nd = _mm256_sub_pd(_mm256_add_pd(rj, addv), vj);
        __m256d mask = _mm256_cmp_pd(nd, dj, _CMP_LT_OQ);
        __m256d merged = _mm256_blendv_pd(dj, nd, mask);
        _mm256_storeu_pd(d + j, merged);
        int bits = _mm256_movemask_pd(mask);
        if (bits) {
            if (bits & 1) pred[j] = im;
            if (bits & 2) pred[j+1] = im;
            if (bits & 4) pred[j+2] = im;
            if (bits & 8) pred[j+3] = im;
        }
    }
    for (; j < dim; ++j) {
        if (scanned[j]) continue;
        double nd = add + row[j] - v[j];
        if (nd < d[j]) { d[j] = nd; pred[j] = im; }
    }
}

// index of minimum d[j] among unscanned columns
static inline int find_min(const double* d, const uint8_t* scanned, int dim) {
    int j = 0, best = -1;
    double mn = 1e300;
    for (; j + 7 < dim; j += 8) {
        // quick skip if all scanned
        uint64_t sc = *reinterpret_cast<const uint64_t*>(scanned + j);
        if (sc == 0x0101010101010101ULL) continue;
        for (int k = 0; k < 8; ++k) {
            if (!scanned[j+k] && d[j+k] < mn) { mn = d[j+k]; best = j+k; }
        }
    }
    for (; j < dim; ++j) if (!scanned[j] && d[j] < mn) { mn = d[j]; best = j; }
    return best;
}

extern "C" int lapjv(int n, const double* cost, int* col_for_row) {
    const int dim = n;
    std::vector<double> v(dim, 0.0), d(dim);
    std::vector<int> rowsol(dim, -1), colsol(dim, -1), pred(dim), matches(dim, 0);
    std::vector<uint8_t> scanned(dim);

    for (int j = dim - 1; j >= 0; --j) {
        double minv = cost[j]; int imin = 0;
        for (int i = 1; i < dim; ++i) {
            double val = cost[(size_t)i * dim + j];
            if (val < minv) { minv = val; imin = i; }
        }
        v[j] = minv;
        if (++matches[imin] == 1) { rowsol[imin] = j; colsol[j] = imin; }
        else colsol[j] = -1;
    }
    std::vector<int> free_rows;
    for (int i = 0; i < dim; ++i) if (rowsol[i] < 0) free_rows.push_back(i);
    {
        std::vector<int> still;
        for (int i : free_rows) {
            double mn1 = BIG, mn2 = BIG; int j1 = 0;
            const double* row = cost + (size_t)i * dim;
            for (int j = 0; j < dim; ++j) {
                double red = row[j] - v[j];
                if (red < mn2) { if (red >= mn1) mn2 = red; else { mn2 = mn1; mn1 = red; j1 = j; } }
            }
            int i0 = colsol[j1];
            if (mn2 - mn1 > 1e-15) v[j1] -= (mn2 - mn1);
            if (i0 < 0) { colsol[j1] = i; rowsol[i] = j1; }
            else if (mn2 - mn1 > 1e-15) { rowsol[i] = j1; colsol[j1] = i; rowsol[i0] = -1; still.push_back(i0); }
            else still.push_back(i);
        }
        free_rows.swap(still);
    }
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<int> list = free_rows; free_rows.clear();
        size_t head = 0; int guard = 0;
        while (head < list.size() && guard < dim * 4) {
            ++guard; int i = list[head++]; if (rowsol[i] >= 0) continue;
            double mn1 = BIG, mn2 = BIG; int j1 = 0;
            const double* row = cost + (size_t)i * dim;
            for (int j = 0; j < dim; ++j) {
                double red = row[j] - v[j];
                if (red < mn2) { if (red >= mn1) mn2 = red; else { mn2 = mn1; mn1 = red; j1 = j; } }
            }
            double h = mn2 - mn1; v[j1] -= h;
            int i0 = colsol[j1]; colsol[j1] = i; rowsol[i] = j1;
            if (i0 >= 0 && i0 != i) { rowsol[i0] = -1; if (h > 1e-15) list.push_back(i0); else free_rows.push_back(i0); }
        }
        for (size_t t = head; t < list.size(); ++t) if (rowsol[list[t]] < 0) free_rows.push_back(list[t]);
        if (free_rows.empty()) break;
    }

    for (int i = 0; i < dim; ++i) {
        if (rowsol[i] >= 0) continue;
        std::memset(scanned.data(), 0, dim);
        const double* rowi = cost + (size_t)i * dim;
        for (int j = 0; j < dim; ++j) { d[j] = rowi[j] - v[j]; pred[j] = i; }
        int last = -1;
        while (true) {
            int jcur = find_min(d.data(), scanned.data(), dim);
            if (jcur < 0) return 1;
            scanned[jcur] = 1;
            if (colsol[jcur] < 0) { last = jcur; break; }
            int im = colsol[jcur];
            double base = cost[(size_t)im * dim + jcur] - v[jcur];
            relax_row(cost + (size_t)im * dim, v.data(), d.data(), pred.data(),
                      scanned.data(), dim, im, d[jcur] - base);
        }
        double mind = d[last];
        for (int j = 0; j < dim; ++j) if (scanned[j]) v[j] += d[j] - mind;
        int j = last;
        while (true) {
            int ip = pred[j]; colsol[j] = ip; int old = rowsol[ip]; rowsol[ip] = j;
            if (ip == i) break; j = old;
        }
    }
    for (int i = 0; i < dim; ++i) col_for_row[i] = rowsol[i];
    return 0;
}
